from format_lecon import Lesson,paras,table,steps
from diagnostics import DIAGNOSTICS
def make(n):return Lesson(DIAGNOSTICS[n-1][0],n)

l=make(9)
l.add('La papillomatose laryngée est une affection liée au HPV qui produit des lésions papillaires du larynx. Son {caractère habituellement bénin} n’exclut ni obstruction ni récidives.',paras('Les papillomes forment des excroissances muqueuses pouvant modifier la vibration et le passage de l’air. La dysphonie peut être la plainte initiale, mais l’importance respiratoire dépend de l’étendue et de la localisation.', 'La confirmation de la nature des lésions est nécessaire : une apparence papillaire ne constitue pas, à elle seule, un résultat histologique. Une récidive connue ne dispense pas d’examiner une évolution inhabituelle.'),(3,6))
l.add('La maladie peut concerner l’enfant et l’adulte. Les {repères épidémiologiques disponibles} ne permettent pas de fournir ici une incidence suisse par groupe d’âge.',paras('Le contexte pédiatrique impose de prendre au sérieux une modification durable du cri ou de la voix, particulièrement si elle s’accompagne d’un bruit respiratoire. Chez l’adulte, une dysphonie persistante nécessite aussi une visualisation adaptée.', 'Les sources retenues décrivent l’association virale et la possibilité de récidives, sans série nationale chiffrée comparable. Le nombre de gestes déjà réalisés décrit le parcours individuel, pas la fréquence dans la population.'),(3,6))
l.add('La prolifération de lésions muqueuses perturbe vibration et parfois ouverture laryngée. Les {mécanismes de récidive et de gêne} expliquent les objectifs limités d’un geste local.',paras('Retirer les lésions visibles peut améliorer la voix ou la respiration sans garantir l’éradication de l’affection virale. Une surveillance reste donc nécessaire après un résultat initial satisfaisant.', 'Les gestes répétés doivent tenir compte de la muqueuse vibrante et du risque de cicatrice. Le traitement cherche un compromis entre contrôle des lésions et préservation de la fonction, adapté à la gravité.'),(3,6))
l.add('L’obstruction respiratoire constitue la priorité en cas de lésions volumineuses ou mal situées. Les {signaux d’aggravation} imposent une réévaluation même chez un patient déjà suivi.',table(['🚩 Signal','Action'],[['Stridor, tirage ou dyspnée croissante.','Évaluation urgente des voies aériennes.'],['Modification du cri et respiration bruyante chez un enfant.','Orientation pédiatrique et ORL adaptée à la gravité.'],['Aggravation rapide ou aspect différent d’une récidive habituelle.','Nouvelle caractérisation ; histologie selon constatations.'],['Persistance après traitement avec gêne fonctionnelle nouvelle.','Rechercher lésion résiduelle, récidive ou conséquence cicatricielle.']]),(3,6))
l.add('L’anamnèse précise le retentissement respiratoire et le parcours des récidives. Les {données longitudinales} aident à interpréter l’examen du jour.',paras('Rechercher début de la dysphonie, gêne à l’effort, bruits respiratoires, épisodes d’obstruction et traitements précédents. Si une histologie existe, récupérer son résultat plutôt que de se contenter du souvenir du mot papillome.', 'Documenter fréquence ressentie des récidives, bénéfice des gestes, séquelles vocales et suivi prévu. Chez l’enfant, recueillir les observations des proches sur le cri, le sommeil et l’effort sans conclure à une simple habitude vocale.'),(3,6))
l.add('L’examen décrit l’étendue des lésions et la perméabilité laryngée. Les {points spécifiques de l’endoscopie} comprennent aussi l’état entre les zones traitées.',paras('Repérer les lésions papillaires, leur effet sur l’ouverture et leur relation avec les plis vocaux. Examiner la mobilité et rechercher les zones cicatricielles ou suspectes.', 'La technique et les conditions de l’examen dépendent de l’âge, de la tolérance et du risque respiratoire. Une exploration incomplète doit être complétée selon la gravité ; elle ne permet pas d’affirmer que la maladie est limitée.'),(3,6))
l.add('Le syndrome associe lésion proliférative muqueuse et retentissement variable. Les {profils cliniques} orientent la priorité thérapeutique.',table(['Profil','Priorité'],[['Dysphonie avec passage aérien préservé.','Caractériser les lésions et le handicap vocal.'],['Extension gênant l’ouverture.','Protéger la respiration.'],['Récidives après gestes.','Revoir la stratégie et préserver la fonction à long terme.'],['Dysphonie persistante sans récidive visible suffisante.','Rechercher cicatrice ou autre mécanisme associé.']]),(3,6))
l.add('Le diagnostic combine l’aspect endoscopique et la confirmation tissulaire. Les {limites du diagnostic visuel} justifient une histologie adaptée.',paras('Le prélèvement permet de confirmer la nature des lésions et d’évaluer une présentation atypique. Il ne faut pas attribuer une masse nouvelle à la papillomatose sur le seul antécédent.', 'Une analyse virale peut répondre à une question spécialisée, mais ne remplace pas la morphologie et l’histologie d’une lésion suspecte. Aucun test de dépistage sanguin systématique n’est proposé ici.'),(3,6))
l.add('Le bilan cartographie la maladie et recherche ses conséquences. Les {explorations hiérarchisées} sont adaptées au risque et au contexte.',paras('9.a — Référence : endoscopie et histologie des lésions selon indication.', '9.b — Première intention : examiner le larynx, la mobilité et le passage de l’air.', '9.c — Adapter l’exploration à l’enfant et aux situations respiratoires difficiles, avec conditions spécialisées appropriées.', '9.d — Étendre le bilan si symptômes ou constatations suggèrent une atteinte plus large ; l’imagerie n’est pas un substitut à la visualisation des lésions muqueuses. Les examens virologiques sont discutés par l’équipe spécialisée.'),(3,6))
l.add('L’{algorithme de la papillomatose} associe sécurité, confirmation et surveillance. Une rémission visible ne supprime pas le risque de nouvelle lésion.',steps('Si obstruction → prise en charge urgente des voies aériennes et des lésions.', 'Sinon → cartographie endoscopique et confirmation histologique adaptée.', 'Choisir le geste selon retentissement, étendue et nécessité de préserver la muqueuse.', 'Planifier le suivi des récidives et des séquelles ; reconsidérer toute évolution atypique.'),(3,6))
l.add('La prise en charge spécialisée traite les lésions gênantes tout en préservant la fonction laryngée. Les {objectifs et limites du traitement} doivent être expliqués dès le départ.',paras('11.A — Maintenir une respiration sûre, améliorer la communication et limiter le retentissement des récidives et des gestes.', '11.B — Les HUG décrivent une prise en charge des lésions par des gestes spécialisés. Le choix dépend de leur siège et de la gêne ; il peut nécessiter plusieurs interventions. Les traitements adjuvants éventuels relèvent d’un centre spécialisé : aucune dose antivirale ou autre prescription hors indication non vérifiée n’est proposée ici.', '11.C — Contrôler lésions résiduelles, récidives, mobilité et cicatrices. Le suivi est individualisé ; une aggravation respiratoire n’attend pas la consultation programmée.', '11.D — Donner un plan clair de surveillance et les signes d’urgence, notamment aux proches de l’enfant. Prévoir l’accompagnement vocal et le retentissement des soins répétés. Aucun geste n’est présenté comme une garantie d’éradication virale.'),(3,6))
l.add('La prévention des complications repose surtout sur l’accès au suivi et la reconnaissance des récidives. Les {distinctions préventives} évitent de confondre prévention virale et traitement d’une lésion présente.',paras('Primaire : la prévention du HPV relève des recommandations nationales de vaccination ; les sources de cette fiche ne permettent pas d’établir un schéma vaccinal ni de promettre un effet curatif sur une papillomatose existante. Secondaire : examiner une dysphonie persistante, notamment un cri modifié chez l’enfant. Tertiaire : surveiller les récidives, anticiper une gêne respiratoire et limiter les séquelles fonctionnelles des traitements.'),(3,6))
l.add('Une papillomatose habituellement bénigne peut obstruer le larynx. La confirmation histologique complète l’endoscopie. Les lésions peuvent récidiver après traitement. Le suivi protège la respiration et la fonction vocale.',refs=(3,6))
l.quiz([('Bénin signifie-t-il sans risque respiratoire ?','Non : une lésion bénigne peut obstruer les voies aériennes.'),('Quel virus est associé à cette maladie ?','Le papillomavirus humain, ou HPV.'),('Une voix altérée peut-elle précéder la gêne respiratoire ?','Oui : les fonctions atteintes dépendent de la localisation et de l’étendue.'),('Une modification durable du cri mérite-t-elle un examen ?','Oui : surtout si elle s’accompagne de bruit ou d’effort respiratoire.'),('L’aspect papillaire suffit-il à une histologie ?','Non : la caractérisation tissulaire repose sur un prélèvement.'),('Un ancien diagnostic dispense-t-il d’examiner une nouvelle masse atypique ?','Non : une modification inhabituelle doit être réévaluée.'),('L’exérèse visible garantit-elle l’éradication virale ?','Non : des récidives restent possibles.'),('Pourquoi préserver la muqueuse pendant les gestes ?','Pour limiter les séquelles vibratoires et cicatricielles.'),('Le nombre de gestes chez un patient donne-t-il une incidence nationale ?','Non : il décrit seulement son parcours.'),('Un examen incomplet permet-il de conclure à une atteinte limitée ?','Non : ses limites doivent être prises en compte.'),('Une aggravation respiratoire peut-elle attendre le rendez-vous prévu ?','Non : elle nécessite une évaluation adaptée à l’urgence.'),('Un traitement adjuvant autorise-t-il une dose non vérifiée ?','Non : indication, statut et posologie demandent une source et une expertise appropriées.'),('La vaccination est-elle présentée ici comme curative ?','Non : aucun effet curatif ni schéma vaccinal n’est établi dans cette fiche.'),('Une voix gênante après traitement signifie-t-elle toujours récidive ?','Non : une cicatrice ou une autre dysfonction peut aussi participer.')],(3,6))
l.write()

l=make(10)
l.add('Le cancer du larynx est une tumeur maligne de cet organe, le plus souvent issue de sa muqueuse. La {localisation tumorale} détermine en partie la précocité des symptômes vocaux.',paras('Une lésion glottique, située au niveau des plis vocaux, peut modifier la vibration tôt dans son évolution. Les tumeurs situées au-dessus ou au-dessous peuvent se manifester différemment avant d’altérer la voix.', 'La majorité appartient aux carcinomes épidermoïdes décrits dans les enseignements ORL. Le type exact doit être établi par l’anatomopathologie ; une dysphonie isolée n’est ni une preuve de cancer ni un motif de rassurer sans examen lorsque celui-ci est indiqué.'),(5,6,10))
l.add('La Ligue suisse contre le cancer annonce environ 260 nouveaux cas annuels en Suisse. Les {limites de ce repère} imposent de ne pas le présenter comme une mesure propre à 2026.',paras('La page consultée ne précise pas la période statistique associée à ce nombre. Il s’agit donc d’un ordre de grandeur publié, pas d’un taux calculé pour l’année en cours. Elle indique que les hommes âgés sont les plus touchés.', 'Le tabac et l’alcool sont des facteurs de risque importants décrits dans les sources ORL. Leur absence ne permet pas d’exclure une tumeur ; le diagnostic reste fondé sur la lésion et son prélèvement.'),(5,6,10))
l.add('La tumeur perturbe la vibration puis peut infiltrer les structures voisines. Les {bases anatomiques et fonctionnelles} expliquent dysphonie, fixation et obstruction.',paras('Au niveau glottique, une modification relativement limitée de la muqueuse peut suffire à altérer la voix. Une extension plus profonde peut réduire la mobilité ; l’immobilité n’est alors pas nécessairement une paralysie nerveuse.', 'L’extension locale peut compromettre le passage de l’air et la déglutition. Le bilan distingue tumeur locale, ganglions et atteinte à distance, car ces dimensions influencent la stratégie et le pronostic. La qualité du timbre ne mesure pas à elle seule le stade.'),(5,6,10))
l.add('Une menace respiratoire est traitée avant le bilan oncologique complet. Les {urgences et signaux suspects} comprennent aussi progression et atteinte de la déglutition.',table(['🚩 Signal','Conduite'],[['Stridor, tirage ou dyspnée.','Prise en charge urgente des voies aériennes avec équipe expérimentée.'],['Déglutition compromise ou fausses routes importantes.','Évaluer sécurité alimentaire et complications respiratoires.'],['Dysphonie persistante ou progressive chez un fumeur.','Examen ORL sans banalisation ; les HUG citent une persistance au-delà de trois semaines.'],['Lésion suspecte, masse cervicale ou otalgie associée.','Bilan accéléré et prélèvement adapté.']])+paras('Le seuil de durée n’est jamais un délai d’attente obligatoire devant un signe d’alarme. Une petite tumeur glottique peut donner une dysphonie sans douleur ni ganglion palpable.'),(5,6,10))
l.add('L’anamnèse précise chronologie, facteurs de risque et conséquences fonctionnelles. Les {questions orientées vers l’extension et le terrain} préparent le bilan et le traitement.',paras('Rechercher persistance, progression, douleur à avaler, otalgie, masse cervicale, gêne respiratoire et perte de poids. Documenter tabac, alcool, antécédents de tumeur et traitements ORL.', 'Évaluer alimentation, communication, comorbidités et soutien disponible. Les besoins du patient et sa capacité à suivre les soins participent au choix entre les stratégies discutées en équipe multidisciplinaire.'),(5,6,10))
l.add('L’examen visualise la lésion et apprécie sa mobilité ainsi que les aires cervicales. Les {constatations utiles au bilan} dépassent la simple confirmation d’une voix rauque.',paras('Décrire localisation, extension visible, surface et mobilité des plis. Examiner bouche, pharynx et cou selon le parcours ORL, en recherchant notamment des adénopathies.', 'Un examen ambulatoire incomplet nécessite un complément. La laryngoscopie et le prélèvement permettent de caractériser les zones suspectes ; leur organisation tient compte du risque respiratoire et des conditions anesthésiques.'),(5,6,10))
l.add('Les syndromes dépendent de la localisation et de l’évolution. Les {profils cliniques} orientent les fonctions à protéger sans remplacer le stade.',table(['Profil','Signification'],[['Dysphonie isolée persistante.','Possible présentation glottique précoce.'],['Douleur, dysphagie ou otalgie.','Rechercher une extension ou une localisation expliquant ces symptômes.'],['Immobilité laryngée.','Possible infiltration ou autre mécanisme à préciser.'],['Masse cervicale.','Atteinte ganglionnaire possible à explorer.'],['Obstruction.','Priorité respiratoire indépendante de la suite du bilan.']]),(5,6,10))
l.add('La confirmation du cancer repose sur l’histologie. Les {étapes entre suspicion et stade} doivent être distinguées explicitement.',paras('L’endoscopie localise et décrit la lésion ; un prélèvement établit sa nature. L’imagerie précise l’extension selon les constatations, mais ne remplace pas l’histologie.', 'Le classement d’extension est établi par l’équipe spécialisée à partir des données complètes. Il ne faut pas assigner un stade sur la seule dysphonie, sur une photographie isolée ou sur l’absence de ganglion palpable.'),(5,6,10))
l.add('Le bilan combine confirmation tissulaire et évaluation de l’extension. Les {examens et leurs fonctions} évitent de confondre recherche d’une lésion et choix du traitement.',paras('9.a — Référence diagnostique : histologie d’un prélèvement approprié.', '9.b — Première intention spécialisée : examen endoscopique du larynx et examen cervical, puis biopsie selon les conditions de sécurité.', '9.c — Compléter l’exploration sous anesthésie lorsque nécessaire ; adapter l’imagerie au terrain et à la question locale ou ganglionnaire.', '9.d — Bilan d’extension par les modalités retenues par l’équipe, notamment imagerie cervicale et recherche d’atteinte à distance selon contexte. Évaluer aussi nutrition, déglutition, fonction vocale et aptitude aux traitements.'),(5,6,10))
l.add('L’{algorithme oncologique} sépare urgence, confirmation et décision multidisciplinaire. Le suivi fonctionnel commence avant le traitement.',steps('Protéger les voies aériennes et la déglutition si elles sont menacées.', 'Visualiser la lésion et obtenir l’histologie.', 'Établir extension, terrain et objectifs avec le patient.', 'Discuter chirurgie, radiothérapie et traitements systémiques selon le dossier.', 'Organiser réhabilitation, surveillance tumorale et prévention des complications.'),(5,6,10))
stoma=l.subwindow('stome','Après laryngectomie totale : anatomie et communication',paras('Après ablation totale du larynx, la trachée débouche définitivement au cou par un trachéostome. Le nez et la bouche ne communiquent plus avec les poumons : l’air destiné à la respiration passe par cet orifice. Cette anatomie est différente d’une trachéotomie temporaire chez un patient dont le larynx est conservé.', 'En cas d’urgence respiratoire, cette séparation doit être signalée immédiatement aux secours et prise en compte par l’équipe. Les consignes de soins du stome, de protection et d’humidification sont enseignées par les professionnels.', 'La perte de la voix laryngée ne signifie pas l’impossibilité de toute communication. Une prothèse trachéo-œsophagienne ou d’autres méthodes de voix de substitution peuvent être proposées avec rééducation. Le choix dépend de l’anatomie, de la capacité d’entretien et des besoins du patient ; une prothèse nécessite un suivi spécialisé.'),(10,6))
l.add('Le traitement est choisi selon l’extension, la fonction laryngée et les objectifs du patient. Les {stratégies et soins associés} visent contrôle tumoral et qualité de vie.',paras('11.A — Contrôler la maladie tout en préservant autant que possible respiration, alimentation et communication. La conservation anatomique du larynx ne garantit pas à elle seule une fonction satisfaisante.', '11.B — Une petite tumeur peut permettre un traitement local conservateur, notamment chirurgical ou radiothérapique selon le dossier. Les formes plus étendues peuvent nécessiter des traitements combinés ou une laryngectomie, parfois totale. La décision appartient à une concertation spécialisée ; aucun protocole médicamenteux ni dose de radiothérapie n’est extrapolé dans cette fiche.')+paras(stoma)+paras('11.C — Surveiller réponse, récidive, complications de déglutition, nutrition et séquelles vocales. Adapter les soins de support et la réhabilitation ; le résultat tumoral et le résultat fonctionnel doivent être évalués séparément.', '11.D — Avant la sortie, prévoir les soins à domicile, les moyens de communication, les rendez-vous et le soutien au sevrage. Après laryngectomie totale, enseigner l’anatomie respiratoire nouvelle et les consignes spécifiques au stome avec l’équipe.'),(5,6,10))
l.add('La prévention associe réduction des facteurs de risque et examen des symptômes persistants. Les {trois niveaux de prévention} se poursuivent après le traitement.',paras('Primaire : soutenir l’arrêt du tabac et la réduction des expositions à risque, notamment l’alcool. Secondaire : ne pas banaliser une dysphonie persistante et confirmer les lésions suspectes. Tertiaire : organiser surveillance oncologique, réhabilitation vocale et de déglutition, nutrition et soutien psychosocial.'),(5,6,10))
l.add('Une dysphonie isolée peut révéler une tumeur glottique. L’histologie confirme le diagnostic et le bilan établit l’extension. Le traitement se décide en équipe spécialisée avec le patient. Après laryngectomie totale, la respiration passe par le trachéostome.',refs=(5,6,10))
l.quiz([('Une tumeur glottique peut-elle donner seulement une dysphonie ?','Oui : la vibration peut être modifiée tôt, sans douleur ni ganglion palpable.'),('L’absence de tabac exclut-elle le cancer ?','Non : le risque ne remplace pas l’examen et l’histologie.'),('Le chiffre de 260 cas correspond-il ici à une mesure de 2026 ?','Non : la page suisse citée ne précise pas la période statistique.'),('Faut-il attendre trois semaines devant un stridor ?','Non : la menace respiratoire impose une prise en charge immédiate.'),('L’imagerie remplace-t-elle la biopsie ?','Non : elle précise surtout l’extension, tandis que l’histologie établit la nature.'),('Une immobilité signifie-t-elle forcément une lésion nerveuse ?','Non : une infiltration tumorale peut aussi fixer le pli.'),('Une voix très mauvaise prouve-t-elle un stade avancé ?','Non : le timbre ne suffit pas à déterminer l’extension.'),('L’absence d’adénopathie palpable établit-elle un stade complet ?','Non : le bilan spécialisé reste nécessaire.'),('Qui choisit la stratégie thérapeutique ?','L’équipe multidisciplinaire avec le patient, selon extension, terrain et objectifs.'),('Conserver anatomiquement le larynx garantit-il sa fonction ?','Non : respiration, déglutition et voix doivent être évaluées séparément.'),('Après ablation totale, la bouche conduit-elle encore aux poumons ?','Non : la trachée débouche au cou par le trachéostome.'),('Une laryngectomie totale équivaut-elle à toute trachéotomie temporaire ?','Non : la séparation définitive des voies aériennes est une différence essentielle.'),('La perte de voix laryngée supprime-t-elle toute communication orale possible ?','Non : une réhabilitation et des moyens de voix de substitution peuvent être proposés.'),('Le suivi porte-t-il seulement sur la récidive tumorale ?','Non : il couvre aussi nutrition, déglutition, respiration, communication et qualité de vie.')],(5,6,10))
l.write()
